async def ensure_module(client):
    modules=await common.paged(client,f"/courses/{COURSE_ID}/modules"); found=next((m for m in modules if m["name"]==MODULE_NAME),None); data={"module[published]":"false"}
    if found:return await common.api(client,"PUT",f"/courses/{COURSE_ID}/modules/{found['id']}",data=data)
    data["module[name]"]=MODULE_NAME; return await common.api(client,"POST",f"/courses/{COURSE_ID}/modules",data=data)

QUESTIONS=[
("Q1 - ethical CTA","Which CTA crosses the lesson boundary?","Only 2 left - guaranteed! when neither claim is verified",["See the five dessert skills you will practice.","Compare the weekly snack-box options.","Choose the car-wash plan that fits your schedule."],"Correct. Urgency, scarcity, and guarantees must be truthful.","Accurate product information and direct comparison can support an informed choice."),
("Q2 - salary label","What does the $76,950 figure mean in this lesson?","BLS May 2024 U.S. median pay for Market Research Analysts and Marketing Specialists",["Guaranteed DFW starting pay","The pay for every marketing worker","A student's expected first salary"],"Correct. Measure, date, geography, and occupation stay visible.","It is a dated national median, not local starting pay or a guarantee."),
("Q3 - openings and growth","Which statement uses the BLS evidence accurately?","The occupation is projected to grow 7% from 2024-34 and average about 87,200 openings per year; these are different measures.",["There will be exactly 87,200 new jobs every year.","Every graduate has a 7% chance of a job.","The figures prove a DFW shortage."],"Correct. Growth and average annual openings are not interchangeable.","The figures do not prove individual outcomes or a local shortage."),
("Q4 - data goal","Why might one Family Fun Pass strategy be best for clicks but not best for sales?","The best measure depends on the campaign goal, and the tables show different results.",["Clicks and sales always mean the same thing.","The strategy with the best artwork always wins.","Focus-group quotes prove future sales."],"Correct. Goal first, then relevant measure, then limitations.","Artwork preference or a quote alone does not settle the decision."),
("Q5 - platform boundary","What counts as the required evidence this week?","The private Canvas/paper reasoning and revision; H&L, Xello, eDynamic, Canva, and Adobe Express are optional supports.",["Two H&L favorites","A Xello School Subjects completion screen","A public social-media post"],"Correct. Standards evidence is reasoning and revision, not a platform click.","No public post or supplemental platform completion is required."),]

async def upsert_quiz(client):
    qs=await common.paged(client,f"/courses/{COURSE_ID}/quizzes"); found=next((q for q in qs if q.get("title")==TITLES[2]),None)
    data={"quiz[title]":TITLES[2],"quiz[description]":"<p>Ungraded, unlimited-retry practice on ethical communication, current source labels, changing conditions, and platform boundaries.</p>","quiz[quiz_type]":"practice_quiz","quiz[published]":"false","quiz[allowed_attempts]":"-1","quiz[show_correct_answers]":"true","quiz[shuffle_answers]":"false"}
    quiz=await common.api(client,"PUT" if found else "POST",f"/courses/{COURSE_ID}/quizzes/{found['id']}" if found else f"/courses/{COURSE_ID}/quizzes",data=data); existing=await common.paged(client,f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions")
    for pos,(name,prompt,correct,wrong,yes,no) in enumerate(QUESTIONS,1):
        old=next((q for q in existing if q.get("question_name")==name),None); payload={"question":{"question_name":name,"question_text":prompt,"question_type":"multiple_choice_question","position":pos,"points_possible":1,"correct_comments":yes,"incorrect_comments":no,"answers":[{"answer_text":correct,"answer_weight":100}]+[{"answer_text":x,"answer_weight":0} for x in wrong]}}; path=f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions/{old['id']}" if old else f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions"; await common.api(client,"PUT" if old else "POST",path,json=payload)
    return await common.api(client,"GET",f"/courses/{COURSE_ID}/quizzes/{quiz['id']}")

